const input = $input.first().json;
const body = (typeof input.body === 'object' && input.body !== null) ? input.body : input;
const required = ['application_id', 'dealer_name', 'full_name', 'email'];
const missing = required.filter(f => !body[f]);

if (missing.length) return [{ json: { ok: false, missing, body } }];

return [{
  json: {
    ok: true,
    application_id: body.application_id,
    dealer_name:    body.dealer_name,
    full_name:      body.full_name,
    email:          body.email,
    rejected_at:    body.rejected_at || new Date().toISOString()
  }
}];

const d = $('Responder 202 — Aceptado').first().json;
const supabaseResp = $input.first().json;

let adminNotes = '';
let location = '';
if (Array.isArray(supabaseResp)) {
  const row = supabaseResp[0] || {};
  adminNotes = row.admin_notes || '';
  location = [row.location_city, row.location_region].filter(Boolean).join(', ');
}

const notesContext = adminNotes
  ? `\n\nNotas internas del equipo (NO incluyas esto literalmente, úsalo solo como contexto para redactar):\n${adminNotes.slice(0, 800)}`
  : '';

const briefing = `Eres redactor senior de Black Label Market, marketplace premium de vehículos de alta gama en España.\nEscribe un email de respuesta a una solicitud de alta de showroom que NO ha sido aprobada.\n\nDatos del solicitante:\n- Showroom: ${d.dealer_name}\n- Contacto: ${d.full_name}\n- Email: ${d.email}${location ? '\n- Ubicación: ' + location : ''}${notesContext}\n\nEl email debe:\n1. Agradecer el interés y el tiempo dedicado a rellenar la solicitud\n2. Comunicar que la solicitud no encaja con el perfil actual de la plataforma (sin dar razones concretas, de forma educada y profesional)\n3. Dejar la puerta abierta a futuras colaboraciones cuando el showroom amplíe su actividad\n4. Ofrecer que pueden volver a solicitar acceso en el futuro\n5. Firma: «El equipo de Black Label Market»\n\nTono: premium, empático, breve. Sin condescendencia. Sin mencionar motivos específicos de rechazo. Devuelve SOLO el HTML del cuerpo (con <p> y <strong>).`;

return [{
  json: {
    ...d,
    adminNotes, location,
    claudeRequest: {
      model: process.env.ANTHROPIC_MODEL || 'claude-haiku-4-5-20251001',
      max_tokens: 800,
      messages: [{ role: 'user', content: briefing }]
    }
  }
}];

const d = $('Preparar prompt email rechazo').first().json;
const claude = $input.first().json;

let body = '';
if (Array.isArray(claude.content)) body = claude.content.map(b => b.text || '').join('\n').trim();
else if (claude.text) body = claude.text;
else body = `<p>Hola ${d.full_name},</p><p>Gracias por tu interés en Black Label Market. Tras revisar la solicitud de <strong>${d.dealer_name}</strong>, en este momento no encaja con el perfil actual de la plataforma.</p><p>Quedamos a tu disposición para cualquier consulta futura.</p><p>El equipo de Black Label Market</p>`;

const MAIL_FROM   = process.env.MAIL_FROM   || 'Black Label Market <no-reply@blacklabelmarket.es>';
const ADMIN_EMAIL = 'marketing@blackseriesagency.es'; // Fijo: notificaciones de Black Label Market siempre a la agencia, nunca al ADMIN_EMAIL compartido con AldeIA (bug real hallado 2026-08-17, ver registro_decisiones.md)

return [{
  json: {
    ...d,
    emailPayload: {
      from: MAIL_FROM, to: [d.email],
      subject: 'Respuesta a tu solicitud — Black Label Market',
      html: body
    },
    slackText: `*❌ Solicitud rechazada*\n\n*Showroom:* ${d.dealer_name}\n*Contacto:* ${d.full_name} (${d.email})\n*Email de rechazo:* enviado`
  }
}];
